if ($conn->query($sql) === TRUE) {
    echo "记录更新成功，影响行数: " . $conn->affected_rows;
}

// PDO 更新示例
$sql = "UPDATE Users SET email='newemail@example.com' WHERE id=1";
$rows = $conn->exec($sql);
echo "记录更新成功，影响行数: $rows";
?>
```

### 删除数据（DELETE）

```php
<?php
