    echo "记录删除成功，影响行数: " . $conn->affected_rows;
}

// PDO 删除示例
$sql = "DELETE FROM Users WHERE id=1";
$rows = $conn->exec($sql);
echo "记录删除成功，影响行数: $rows";
?>
```

## 四、预处理语句与 SQL 注入防护

预处理语句（Prepared Statements）是防御 SQL 注入攻击的标准做法。

### MySQLi 预处理语句

```php
<?php
$conn = new mysqli($servername, $username, $password, $dbname);

if ($conn->connect_error) {
    die("连接失败: " . $conn->connect_error);
}

// 创建预处理语句
$stmt = $conn->prepare("INSERT INTO Users (name, email) VALUES (?, ?)");
// 绑定参数：s 表示字符串类型，ss 表示两个字符串参数
$stmt->bind_param("ss", $name, $email);

// 设置参数并执行
$name = "王五";
$email = "wangwu@example.com";
$stmt->execute();

echo "新记录插入成功，ID 为: " . $stmt->insert_id;

$stmt->close();
$conn->close();
?>
```

### PDO 预处理语句

```php
<?php
try {
    $conn = new PDO("mysql:host=$servername;dbname=$dbname;charset=utf8", $username, $password);
    $conn->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

    $stmt = $conn->prepare("INSERT INTO Users (name, email) VALUES (:name, :email)");

    $name = "赵六";
    $email = "zhaoliu@example.com";
    $stmt->execute([':name' => $name, ':email' => $email]);

    echo "新记录插入成功，ID 为: " . $conn->lastInsertId();
} catch (PDOException $e) {
    echo "插入失败: " . $e->getMessage();
}
?>
```

### 使用预处理语句查询

```php
<?php
// MySQLi 查询预处理
$stmt = $conn->prepare("SELECT id, name, email FROM Users WHERE id > ?");
$stmt->bind_param("i", $minId);
$minId = 2;
$stmt->execute();
$result = $stmt->get_result();

while ($row = $result->fetch_assoc()) {
    echo "ID: " . $row["id"] . " - Name: " . $row["name"] . " - Email: " . $row["email"] . "<br>";
}
$stmt->close();

// PDO 查询预处理
$stmt = $conn->prepare("SELECT id, name, email FROM Users WHERE id > :minId");
$stmt->execute([':minId' => 2]);
while ($row = $stmt->fetch(PDO::FETCH_ASSOC)) {
    echo "ID: " . $row['id'] . " - Name: " . $row['name'] . " - Email: " . $row['email'] . "<br>";
}
?>
```

## 五、错误处理与最佳实践

### 错误处理机制

```php
<?php
// MySQLi 错误处理
if ($conn->connect_error) {
    die("连接失败: " . $conn->connect_error);
}

$result = $conn->query($sql);
if (!$result) {
    echo "查询错误: " . $conn->error;
}

// PDO 错误处理（异常模式）
try {
    $conn = new PDO("mysql:host=$servername;dbname=$dbname", $username, $password);
    $conn->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
} catch (PDOException $e) {
    echo "连接失败: " . $e->getMessage();
}
?>
```

### 推荐的最佳实践

| 实践建议 | 说明 |
| :--- | :--- |
| **使用预处理语句** | 永远不要直接拼接用户输入到 SQL 中，使用预处理语句防止 SQL 注入 |
| **配置合适的字符集** | 使用 `charset=utf8mb4` 支持完整的 Unicode 和 Emoji 字符 |
| **密码不要硬编码** | 使用环境变量或配置文件存储数据库密码 |
| **生产环境关闭错误显示** | 使用 `error_reporting(0)` 避免暴露敏感信息 |
| **设置合理的连接超时** | 避免长时间等待无法响应的数据库连接 |
| **使用连接池或持久连接** | 减少频繁创建和销毁连接的开销 |

### 环境变量配置示例

```php
<?php
// 从环境变量读取敏感信息
$host = getenv('DB_HOST') ?: 'localhost';
$dbname = getenv('DB_NAME') ?: 'myapp';
$user = getenv('DB_USER') ?: 'appuser';
$pass = getenv('DB_PASS') ?: '';
?>
```

## 六、SSL 加密连接

对于生产环境，建议使用 SSL/TLS 加密连接以保护数据传输安全。

```php
<?php
// MySQLi SSL 连接示例
$conn = mysqli_init();

mysqli_ssl_set(
    $conn,
    null,
    null,
    "/path/to/ca-cert.pem",
    null,
    null
);

mysqli_real_connect(
    $conn,
    $host,
    $username,
    $password,
    $dbname,
    3306,
    MYSQLI_CLIENT_SSL
);

if (mysqli_connect_errno($conn)) {
    die("SSL 连接失败: " . mysqli_connect_error());
}
?>
```

## 总结

PHP 与 MySQL 的配合使用是 Web 开发中的标准实践，核心要点可归纳为：

1. **选择扩展**：MySQLi 适合专属 MySQL 项目，PDO 适合跨数据库或需要更高抽象层的情况
2. **安全第一**：始终使用预处理语句防止 SQL 注入，合理配置字符集和错误处理
3. **连接配置**：密码避免硬编码，生产环境使用 SSL 加密连接

掌握这些基础操作后，就可以进一步学习事务处理、存储过程调用、批量操作等高级特性，构建出更强大、安全的 Web 应用。

