## 四、预处理语句与 SQL 注入防护

预处理语句是防御 SQL 注入攻击的标准做法，使用时应严格遵守。

### pgsql 扩展中的预处理语句

```php
<?php
$dbconn = pg_connect("host=localhost dbname=mydatabase user=myuser password=mypassword");

if (!$dbconn) {
    die("连接失败：" . pg_last_error());
}

// 使用 pg_prepare 创建预处理语句（$1, $2 是位置占位符）
$result = pg_prepare($dbconn, "insert_query", "INSERT INTO inventory (name, quantity) VALUES ($1, $2)");

if (!$result) {
    die("预处理失败：" . pg_last_error($dbconn));
}

// 执行预处理语句
$result = pg_execute($dbconn, "insert_query", array("banana", 150));

if ($result) {
    echo "数据插入成功";
} else {
    echo "插入失败：" . pg_last_error($dbconn);
}

// 查询预处理
$result = pg_prepare($dbconn, "select_query", "SELECT id, name, quantity FROM inventory WHERE quantity > $1");
$result = pg_execute($dbconn, "select_query", array(100));

while ($row = pg_fetch_assoc($result)) {
    echo "ID: " . $row['id'] . " - Name: " . $row['name'] . " - Quantity: " . $row['quantity'] . "<br>";
}

pg_free_result($result);
pg_close($dbconn);
?>
```

### PDO 预处理语句

```php
<?php
try {
    $pdo = new PDO("pgsql:host=localhost;dbname=mydatabase", "myuser", "mypassword");
    $pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

    // 使用命名参数（推荐，可读性更好）
    $stmt = $pdo->prepare("INSERT INTO inventory (name, quantity) VALUES (:name, :quantity)");
    $stmt->execute([':name' => 'banana', ':quantity' => 150]);
    echo "插入成功，ID: " . $pdo->lastInsertId('inventory_id_seq');

    // 使用位置占位符
    $stmt = $pdo->prepare("INSERT INTO inventory (name, quantity) VALUES (?, ?)");
    $stmt->execute(['apple', 100]);
    echo "插入成功";

    // 查询预处理
    $stmt = $pdo->prepare("SELECT id, name, quantity FROM inventory WHERE quantity > :minQty");
    $stmt->execute([':minQty' => 50]);
    while ($row = $stmt->fetch(PDO::FETCH_ASSOC)) {
        echo "ID: " . $row['id'] . " - Name: " . $row['name'] . " - Quantity: " . $row['quantity'] . "<br>";
    }
} catch (PDOException $e) {
    echo "操作失败：" . $e->getMessage();
}
?>
```

## 五、事务处理

PostgreSQL 支持完整的 ACID 事务，PHP 中也可以很好地管理事务操作。

### pgsql 扩展事务处理

```php
<?php
$dbconn = pg_connect("host=localhost dbname=mydatabase user=myuser password=mypassword");

if (!$dbconn) {
    die("连接失败：" . pg_last_error());
}

// 开始事务
pg_query($dbconn, "BEGIN");

try {
    pg_query($dbconn, "UPDATE accounts SET balance = balance - 100 WHERE id = 1");
    pg_query($dbconn, "UPDATE accounts SET balance = balance + 100 WHERE id = 2");

    // 提交事务
    pg_query($dbconn, "COMMIT");
    echo "事务提交成功";
} catch (Exception $e) {
    // 回滚事务
    pg_query($dbconn, "ROLLBACK");
    echo "事务回滚：" . $e->getMessage();
}

pg_close($dbconn);
?>
```

### PDO 事务处理

```php
<?php
try {
    $pdo = new PDO("pgsql:host=localhost;dbname=mydatabase", "myuser", "mypassword");
    $pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

    // 开始事务
    $pdo->beginTransaction();

    $pdo->exec("UPDATE accounts SET balance = balance - 100 WHERE id = 1");
    $pdo->exec("UPDATE accounts SET balance = balance + 100 WHERE id = 2");

    // 提交事务
    $pdo->commit();
    echo "事务提交成功";
} catch (PDOException $e) {
    // 回滚事务
    if ($pdo->inTransaction()) {
        $pdo->rollBack();
    }
    echo "事务回滚：" . $e->getMessage();
}
?>
```

## 六、错误处理机制

### pgsql 扩展错误处理

```php
<?php
$dbconn = pg_connect("host=localhost dbname=mydatabase user=myuser password=mypassword");

if (!$dbconn) {
    die("连接失败：" . pg_last_error());
}

$result = pg_query($dbconn, "SELECT * FROM non_existent_table");
if (!$result) {
    // 获取详细的错误信息
    $error = pg_last_error($dbconn);
    $errorCode = pg_result_error_field($result, PGSQL_DIAG_SQLSTATE);
    echo "错误代码: $errorCode<br>";
    echo "错误信息: $error<br>";
} else {
    pg_free_result($result);
}

// 获取当前连接的最后错误
if (pg_last_error($dbconn)) {
    echo "最近操作发生错误：" . pg_last_error($dbconn);
}

pg_close($dbconn);
?>
```

### PDO 错误处理

```php
<?php
try {
    $pdo = new PDO("pgsql:host=localhost;dbname=mydatabase", "myuser", "mypassword");
    // 设置错误模式为异常
    $pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

    $pdo->query("SELECT * FROM non_existent_table");
} catch (PDOException $e) {
    echo "错误代码: " . $e->getCode() . "<br>";
    echo "错误信息: " . $e->getMessage() . "<br>";
    echo "错误文件: " . $e->getFile() . "<br>";
    echo "错误行号: " . $e->getLine() . "<br>";
}
?>
```

## 七、连接池与持久连接

### pgsql 扩展持久连接

```php
<?php
// 使用 PGSQL_CONNECT_FORCE_NEW 强制建立新连接
$dbconn = pg_connect("host=localhost dbname=mydatabase user=myuser password=mypassword", PGSQL_CONNECT_FORCE_NEW);

// 使用 pg_pconnect() 建立持久连接
$dbconn = pg_pconnect("host=localhost dbname=mydatabase user=myuser password=mypassword");
if ($dbconn) {
    echo "持久连接建立成功";
} else {
    echo "连接失败：" . pg_last_error();
}
?>
```

### PDO 持久连接

```php
<?php
// 在 DSN 中添加 persist 参数
$dsn = "pgsql:host=localhost;dbname=mydatabase;persist=true";
try {
    $pdo = new PDO($dsn, "myuser", "mypassword");
    echo "持久连接建立成功";
} catch (PDOException $e) {
    echo "连接失败：" . $e->getMessage();
}
?>
```

## 八、操作 PostgreSQL 特有数据类型

### JSON/JSONB 数据类型操作

```php
<?php
// 插入 JSON 数据
$jsonData = json_encode(['name' => 'product1', 'tags' => ['electronics', 'sale']]);
$query = "INSERT INTO products (name, metadata) VALUES ('Product A', '$jsonData')";

// 查询 JSON 数据
$query = "SELECT metadata->>'name' as meta_name FROM products";
$result = pg_query($dbconn, $query);
while ($row = pg_fetch_assoc($result)) {
    echo "元数据中的名称: " . $row['meta_name'] . "<br>";
}

// PDO 方式
$stmt = $pdo->prepare("SELECT metadata->>'name' as meta_name FROM products");
$stmt->execute();
while ($row = $stmt->fetch(PDO::FETCH_ASSOC)) {
    echo "元数据中的名称: " . $row['meta_name'] . "<br>";
}
?>
```

### UUID 类型操作

```php
<?php
// PostgreSQL 需要启用 uuid-ossp 扩展
// 执行: CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

// 插入 UUID
$query = "INSERT INTO users (id, name) VALUES (gen_random_uuid(), 'John Doe')";

// 查询 UUID
$query = "SELECT id, name FROM users";
$result = pg_query($dbconn, $query);
while ($row = pg_fetch_assoc($result)) {
    echo "UUID: " . $row['id'] . " - Name: " . $row['name'] . "<br>";
}
?>
```

## 九、数据库性能优化建议

| 建议 | 说明 |
| :--- | :--- |
| **使用索引** | 为经常查询的列建立索引，注意避免过多索引影响写入性能 |
| **使用连接池** | 减少频繁创建和销毁连接的开销 |
| **批量操作** | 使用 `INSERT INTO ... VALUES (...), (...), (...)` 或 `COPY` 命令批量导入 |
| **预处理语句** | 使用预处理语句提升重复查询的性能 |
| **合理设置连接超时** | 避免长时间等待无法响应的数据库连接 |
| **监控慢查询** | 利用 PostgreSQL 的 `pg_stat_statements` 扩展分析慢查询 |

## 十、完整的连接配置示例

```php
<?php
class Database {
    private static ?PDO $instance = null;

    private function __construct() {}

    public static function getInstance(): PDO {
        if (self::$instance === null) {
            $config = [
                'host' => getenv('DB_HOST') ?: 'localhost',
                'port' => getenv('DB_PORT') ?: '5432',
                'dbname' => getenv('DB_NAME') ?: 'myapp',
                'user' => getenv('DB_USER') ?: 'appuser',
                'password' => getenv('DB_PASS') ?: '',
                'sslmode' => getenv('DB_SSL') ?: 'disable',
            ];

            $dsn = sprintf(
                "pgsql:host=%s;port=%s;dbname=%s;sslmode=%s",
                $config['host'],
                $config['port'],
                $config['dbname'],
                $config['sslmode']
            );

            try {
                self::$instance = new PDO($dsn, $config['user'], $config['password']);
                self::$instance->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
                self::$instance->setAttribute(PDO::ATTR_DEFAULT_FETCH_MODE, PDO::FETCH_ASSOC);
            } catch (PDOException $e) {
                die("数据库连接失败: " . $e->getMessage());
            }
        }
        return self::$instance;
    }
}

// 使用示例
$db = Database::getInstance();
$stmt = $db->query("SELECT * FROM inventory");
while ($row = $stmt->fetch()) {
    print_r($row);
}
?>
```

## 总结

PHP 与 PostgreSQL 的配合使用是现代 Web 开发中的常见实践，核心要点可归纳为：

1. **选择扩展**：pgsql 扩展适合 PostgreSQL 专属高性能项目，PDO_PGSQL 适合跨数据库或需要更高抽象层的项目
2. **安全第一**：始终使用预处理语句防止 SQL 注入，合理配置错误处理
3. **连接配置**：密码避免硬编码，生产环境注意连接池和超时配置
4. **事务处理**：使用事务保证数据一致性
5. **特有功能**：利用 PostgreSQL 的 JSON、UUID 等高级数据类型

掌握这些基础操作后，可以进一步学习 PostgreSQL 的存储过程、全文搜索、高级索引和分区表等特性，构建更强大的 Web 应用。
